contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 value) public {
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool ownerIsCaller = (c.owner() == address(this));

        assert(reverted == (!ownerIsCaller || value > balBefore));
    }
}

