pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 value) internal {
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool ownerIsCaller = (c.owner() == address(this));
        assertTrue(reverted == (!ownerIsCaller || value > balBefore));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
